// Enforce one-time global initialization semantics using global attributes.
// If already started, bail to respect library's intended single-init contract.
int started = FUZZ_GET_ATTR_INT_GLOBAL("coap_started");
if (started) {
  FUZZ_BAIL();
}
// Perform library-global initialization.
coap_startup();
// Mark library as started for downstream stubs (e.g., coap_cleanup).
FUZZ_SET_ATTR_INT_GLOBAL("coap_started", 1);
// No inputs/outputs; process-global state only.

// Enforce correct ordering: cleanup must follow a prior successful startup
// and should not be called more than once without a re-startup.
int started = FUZZ_GET_ATTR_INT_GLOBAL("coap_started");
if (!started) {
  FUZZ_BAIL();
