import random
import ipaddress
import string

# Data type: hostname or IP literal
# Used by stubs via FUZZ_PARAM_STR() for inputs like hostnames, multicast group names,
# proxy host lists, and URI components. Provide a bytes buffer that, when read as a
# string by the harness, yields a valid and interesting address-like token.

MAX_BYTES = 4096

_HOST_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
_TLD_CHOICES = [
    "com", "org", "net", "io", "local", "example", "invalid",
    "arpa", "test", "co", "dev"
]

# Common IPv4 multicast ranges and special-use addresses
_IPV4_MCAST = [
    "224.0.0.1",      # all hosts
    "224.0.0.9",      # RIP v2
    "239.255.255.250" # SSDP
]

# Common IPv6 multicast and special addresses
_IPV6_MCAST = [
    "ff02::1",    # all nodes (link-local)
    "ff02::2",    # all routers (link-local)
    "ff05::2",    # all routers (site-local)
]

# Some unicast variety
_IPV4_UNICAST = [
    "127.0.0.1", "0.0.0.0", "192.0.2.1", "198.51.100.5", "203.0.113.7",
    "10.0.0.1", "172.16.0.10", "192.168.1.100"
]

_IPV6_UNICAST = [
    "::1", "::", "2001:db8::1", "fe80::1", "2001:db8:abcd:1::42"
]

_IDNA_SAMPLES = [
    # simple punycode-like (not actual punycode here, but valid label bytes)
    "xn--exmple-cua", "xn--d1acufc"  # example in Cyrillic punycode form
]

_DEF_HOSTS = [
    "localhost", "example.com", "test.local", "coap.example", "node-1",
]

def _rand_hostname(rng: random.Random) -> str:
    # Build 2-4 labels, each 1-20 chars, start/end alnum, internal hyphens allowed
    nlabels = rng.randint(2, 4)
    labels = []
    for i in range(nlabels - 1):
        L = rng.randint(1, 12)
        s = []
        for j in range(L):
            s.append(rng.choice(_HOST_LABEL_CHARS))
        # Ensure label does not start or end with '-'
        if s[0] == '-':
            s[0] = rng.choice(string.ascii_lowercase + string.digits)
        if s[-1] == '-':
            s[-1] = rng.choice(string.ascii_lowercase + string.digits)
        labels.append(''.join(s))
    # TLD
    if rng.random() < 0.7:
        tld = rng.choice(_TLD_CHOICES)
    else:
        tld = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(2, 6)))
    labels.append(tld)
    return '.'.join(labels)

def _rand_ipv4(rng: random.Random, multicast_bias: float = 0.3) -> str:
    if rng.random() < multicast_bias:
        return rng.choice(_IPV4_MCAST)
    return rng.choice(_IPV4_UNICAST) if rng.random() < 0.5 else str(ipaddress.IPv4Address(rng.getrandbits(32)))

def _rand_ipv6(rng: random.Random, multicast_bias: float = 0.3, bracket: bool = False) -> str:
    addr = rng.choice(_IPV6_MCAST) if rng.random() < multicast_bias else (
        rng.choice(_IPV6_UNICAST) if rng.random() < 0.5 else str(ipaddress.IPv6Address(rng.getrandbits(128)))
    )
    if bracket:
        return f"[{addr}]"
    return addr

def _rand_unix_domain(rng: random.Random) -> str:
    # libcoap UDS host parsing typically uses a leading '/', optionally percent-encoded
    # Provide both plain and %2F encoded variants
    parts = ["/tmp", "coap", f"sock{rng.randint(0,999)}"]
    path = "/".join(parts)
    if rng.random() < 0.5:
        return path
    # percent-encode slashes as %2F in host component style
    return path.replace('/', '%2F')

def _rand_groupname(rng: random.Random) -> str:
    # Favor multicast literals as coap_join_mcast_group_intf() expects multicast
    if rng.random() < 0.6:
        return rng.choice(_IPV4_MCAST)
    if rng.random() < 0.5:
        return rng.choice(_IPV6_MCAST)
    # Fallback to a reasonable multicast name or mDNS name
    return "ff05::1:3" if rng.random() < 0.5 else "224.0.0.251"

def _rand_choice(rng: random.Random) -> str:
    p = rng.random()
    if p < 0.20:
        return _rand_hostname(rng)
    elif p < 0.40:
        return _rand_ipv4(rng)
    elif p < 0.60:
        # Occasionally bracket IPv6 for URI contexts
        return _rand_ipv6(rng, bracket=rng.random() < 0.5)
    elif p < 0.70:
        return rng.choice(_DEF_HOSTS)
    elif p < 0.80:
        return rng.choice(_IDNA_SAMPLES)
    elif p < 0.90:
        return _rand_unix_domain(rng)
    else:
        return _rand_groupname(rng)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a small corpus of address-like strings; harness will draw FUZZ_PARAM_STR
    # potentially multiple times, so provide multiple newline-separated entries.
    entries = []
    # Mandatory common entries first
    entries.append("localhost")
    entries.append("127.0.0.1")
    entries.append("::1")
    entries.append("224.0.0.1")
    entries.append("ff02::1")
    # A few randomized entries to cover variety
    count = 15
    for _ in range(count):
        s = _rand_choice(rng)
        # Bound individual line length to something acceptable by the stubs (<=64 commonly)
        if len(s) > 64:
            s = s[:64]
        entries.append(s)
    blob = ("\n".join(entries)).encode("utf-8")
    if len(blob) > MAX_BYTES:
        blob = blob[:MAX_BYTES]
    return blob

import random
import string
from typing import List

# Generator for interesting filesystem path bytes for libcoap fuzzers expecting filenames
# We output a sequence of NUL-terminated path strings within a single bytes buffer.

MAX_BUF = 4096

POSIX_DIRS = [
    b"/etc/ssl/certs",
    b"/etc/ssl",
    b"/etc/ca-certificates",
    b"/usr/share/ca-certificates",
    b"/var/tmp",
    b"/tmp",
]

POSIX_FILES = [
    b"/etc/ssl/cert.pem",
    b"/etc/ssl/certs/ca-certificates.crt",
    b"/etc/ssl/certs/ca-bundle.crt",
    b"/tmp/libcoap-ca.pem",
]

WIN_DIRS = [
    b"C:\\Windows\\System32\\Config\\SystemProfile",
    b"C:\\Windows\\Temp",
    b"C:\\Temp",
]

WIN_FILES = [
    b"C:\\Windows\\Temp\\libcoap-ca.pem",
    b"C:\\Temp\\coap_persist.dat",
]

REL_DIRS = [
    b".", b"..", b"./data", b"./out", b"./certs", b"../certs",
]

REL_FILES = [
    b"./ca.pem",
    b"./certs/ca.pem",
    b"./persist/obs.json",
    b"./persist/dyn_resources.json",
]

# Some names to exercise different extensions and behaviors
BASENAMES = [
    b"ca.pem", b"ca.crt", b"bundle.pem", b"bundle.crt", b"index.txt",
    b"observe.dat", b"observe.json", b"dyn_resources.json", b"obs_cnt.bin",
]

# Path variants: absolute POSIX, absolute Windows, relative, UNC-like, long segments, spaces, utf-8
EXTRA_VARIANTS = [
    b"/var/lib/libcoap/persist/observe.json",
    b"/var/lib/libcoap/persist/dyn_resources.json",
    b"/var/lib/libcoap/persist/obs_cnt.bin",
    b"C:\\ProgramData\\libcoap\\persist\\observe.json",
    b"C:\\ProgramData\\libcoap\\persist\\dyn_resources.json",
    b"C:\\ProgramData\\libcoap\\persist\\obs_cnt.bin",
    b"\\\\server\\share\\libcoap\\ca-bundle.crt",
    b"./with space/ca bundle.pem",
    # UTF-8 path components (common locales)
    "./certs/mañana.pem".encode("utf-8"),
    "./证书/根.pem".encode("utf-8"),
]

def _to_bytes(s: str) -> bytes:
    return s.encode('utf-8')

def rnd_basename(r: random.Random) -> bytes:
    ext = r.choice([b".pem", b".crt", b".der", b".txt", b".json", b".bin"])
    stem_len = r.randint(3, 12)
    # Build a random ASCII stem and then encode to bytes
    alphabet = string.ascii_letters + string.digits + "-_"
    stem_str = ''.join(r.choice(alphabet) for _ in range(stem_len))
    stem = stem_str.encode('ascii')
    return stem + ext

def join_path(parts: List[bytes]) -> bytes:
    if len(parts) == 0:
        return b"."
    p0 = parts[0]
    if b":" in p0 or p0.startswith(b"\\\\"):
        sep = b"\\"
    else:
        sep = b"/"
    out = parts[0]
    for p in parts[1:]:
        if not out.endswith(sep):
            out += sep
        out += p
    return out

def make_posix_file(r: random.Random) -> bytes:
    candidate = join_path([r.choice(POSIX_DIRS), r.choice(BASENAMES + [rnd_basename(r)])])
    return r.choice(POSIX_FILES + [candidate])

def make_posix_dir(r: random.Random) -> bytes:
    return r.choice(POSIX_DIRS)

def make_win_file(r: random.Random) -> bytes:
    candidate = join_path([r.choice(WIN_DIRS), r.choice(BASENAMES + [rnd_basename(r)])])
    return r.choice(WIN_FILES + [candidate])

def make_win_dir(r: random.Random) -> bytes:
    return r.choice(WIN_DIRS)

def make_rel_file(r: random.Random) -> bytes:
    candidate = join_path([r.choice(REL_DIRS), r.choice(BASENAMES + [rnd_basename(r)])])
    return r.choice(REL_FILES + [candidate])

def make_rel_dir(r: random.Random) -> bytes:
    return r.choice(REL_DIRS)

def mutate_with_env(path: bytes, r: random.Random) -> bytes:
    # Occasionally prepend environment variables
    if r.random() < 0.2:
        if b":" in path or path.startswith(b"\\\\"):
            var = r.choice([b"%TEMP%", b"%TMP%", b"%APPDATA%"])
            # If path already has separators, take basename to concat
            tail = path.split(b"\\")[-1]
            return join_path([var, tail])
        else:
            var = r.choice([b"$HOME", b"$TMPDIR", b"${HOME}"])
            tail = path.split(b"/")[-1]
            return join_path([var, tail])
    return path

def maybe_make_dir(path: bytes, r: random.Random) -> bytes:
    # Sometimes convert to directory by trimming last segment
    if r.random() < 0.3:
        if b"/" in path:
            return path.rsplit(b"/", 1)[0]
        if b"\\" in path:
            return path.rsplit(b"\\", 1)[0]
    return path

def generate_paths(r: random.Random, count: int) -> List[bytes]:
    paths: List[bytes] = []
    producers = [
        make_posix_file, make_posix_dir,
        make_win_file, make_win_dir,
        make_rel_file, make_rel_dir,
    ]
    pool = EXTRA_VARIANTS.copy()
    for _ in range(max(0, count - len(pool))):
        f = r.choice(producers)
        p = f(r)
        p = mutate_with_env(p, r)
        p = maybe_make_dir(p, r)
        if r.random() < 0.1:
            long_seg = b"a" * r.randint(50, 180)
            p = join_path([p, long_seg])
        pool.append(p)
    r.shuffle(pool)
    return pool[:count]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    want = 16
    paths = generate_paths(r, want)

    chunks: List[bytes] = []
    total = 0
    for p in paths:
        if not p:
            p = b"."
        need = len(p) + 1
        if total + need > MAX_BUF:
            break
        chunks.append(p + b"\x00")
        total += need

    if not chunks:
        chunks = [b"/etc/ssl/certs\x00", b"./persist/obs.json\x00"]

    return b"".join(chunks)
